   132	    // You can save offline waypoints without verifying the address (we will geocode it on the backend)
   133	    // We're going to prevent saving those addresses in the recent waypoints though since they could be invalid addresses
   134	    // However, in the backend once we verify the address, we will save the waypoint in the recent waypoints NVP
   135	    if (!lodashHas(waypoint, 'lat') || !lodashHas(waypoint, 'lng')) {
   136	        return;
   137	    }
